<?php
$user=current_user();$error=null;
if(request_method('POST')){try{verify_csrf();$action=post_string('action');if($action==='profile'){$name=post_string('full_name');$email=strtolower(post_string('email'));$phone=post_string('phone');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid name and email.');$stmt=db()->prepare('SELECT COUNT(*) FROM users WHERE email=? AND user_id<>?');$stmt->execute([$email,$user['user_id']]);if((int)$stmt->fetchColumn()>0)throw new RuntimeException('That email is already used by another account.');if($user['role_name']==='Patient'){$patientDup=db()->prepare("SELECT COUNT(*) FROM patients WHERE user_id<>? AND ((phone=? AND phone<>'') OR (email=? AND email<>''))");$patientDup->execute([$user['user_id'],$phone,$email]);if((int)$patientDup->fetchColumn()>0)throw new RuntimeException('Another patient record already uses that phone or email. Contact reception for assistance.');}db()->prepare('UPDATE users SET full_name=?,email=?,phone=? WHERE user_id=?')->execute([$name,$email,nullable($phone),$user['user_id']]);if($user['role_name']==='Patient')db()->prepare('UPDATE patients SET full_name=?,email=?,phone=? WHERE user_id=?')->execute([$name,$email,nullable($phone),$user['user_id']]);log_action('UPDATE_PROFILE','users',$user['user_id'],null,['full_name'=>$name,'email'=>$email]);current_user(true);flash('profile','Profile updated.','success');redirect_to('profile');}if($action==='password'){$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');if(!password_verify($current,$user['password_hash']))throw new RuntimeException('Current password is incorrect.');if(strlen($new)<8||$new!==$confirm)throw new RuntimeException('New passwords must match and contain at least 8 characters.');db()->prepare('UPDATE users SET password_hash=? WHERE user_id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$user['user_id']]);log_action('CHANGE_PASSWORD','users',$user['user_id']);flash('profile','Password changed successfully.','success');redirect_to('profile');}}catch(Throwable $e){$error=$e->getMessage();}}
$user=current_user(true);$patient=patient_for_current_user();$doctor=doctor_for_current_user();
?>
<div class="page-header"><div><h2>My profile</h2><p>Manage your account details and password.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<div class="grid grid-3"><div class="card"><div style="text-align:center;padding:12px"><div class="avatar" style="width:82px;height:82px;font-size:28px;margin:0 auto 13px"><?=e(strtoupper(substr($user['full_name'],0,1)))?></div><h3 class="mb-0"><?=e($user['full_name'])?></h3><p class="text-muted mt-0"><?=e($user['role_name'])?></p><span class="badge badge-<?=status_class($user['account_status'])?>"><?=e($user['account_status'])?></span></div><div class="divider"></div><div><div class="table-subtitle">Username</div><div class="table-title"><?=e($user['username'])?></div><br><div class="table-subtitle">Last login</div><div class="table-title"><?=format_date($user['last_login'],'d M Y, h:i A')?></div><?php if($patient):?><br><div class="table-subtitle">Patient code</div><div class="table-title"><?=e($patient['patient_code'])?></div><?php endif;?><?php if($doctor):?><br><div class="table-subtitle">Doctor code</div><div class="table-title"><?=e($doctor['doctor_code'])?></div><?php endif;?></div></div>
<div class="card" style="grid-column:span 2"><div class="card-header"><div><h3>Account information</h3><p>These details are used throughout the system.</p></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="profile"><div class="form-grid"><div class="field"><label class="required">Full name</label><input class="input" name="full_name" value="<?=e($user['full_name'])?>" required></div><div class="field"><label class="required">Email</label><input class="input" type="email" name="email" value="<?=e($user['email'])?>" required></div><div class="field"><label>Phone</label><input class="input" name="phone" value="<?=e($user['phone']??'')?>"></div><div class="field"><label>Role</label><input class="input" value="<?=e($user['role_name'])?>" disabled></div></div><button class="btn btn-primary" type="submit">Save profile</button></form><div class="divider"></div><div class="card-header"><div><h3>Change password</h3><p>Use a unique password of at least eight characters.</p></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="password"><div class="form-grid form-grid-3"><div class="field"><label class="required">Current password</label><input class="input" type="password" name="current_password" required></div><div class="field"><label class="required">New password</label><input class="input" type="password" name="new_password" minlength="8" required></div><div class="field"><label class="required">Confirm new password</label><input class="input" type="password" name="confirm_password" minlength="8" required></div></div><button class="btn btn-light" type="submit">Change password</button></form></div></div>
